//! Checks the rank filter against output recorded from a real ImageJ build.
//!
//! Fixture generated by `parity/java/RankFilterMinMax.java` via
//! `./parity/record.sh`. MIN and MAX select an input value rather than
//! computing one, so the comparison is exact: no arithmetic happens that could
//! introduce a last-ULP difference, and a tolerance would only hide a genuine
//! kernel-shape error.

use std::path::Path;

use qupath_filters::{RankOp, rank};

struct Case {
    op: RankOp,
    width: usize,
    radius: f64,
    input: Vec<f32>,
    output: Vec<f32>,
}

fn parse(text: &str) -> Vec<Case> {
    let mut cases = Vec::new();
    for block in text.split("{\n      \"op\"").skip(1) {
        let op = match between(block, ": \"", "\"") {
            "min" => RankOp::Min,
            "max" => RankOp::Max,
            other => panic!("unknown op {other}"),
        };
        cases.push(Case {
            op,
            width: field(block, "\"width\": ").parse().expect("width"),
            radius: field(block, "\"radius\": ").parse().expect("radius"),
            input: array(block, "\"input\": ["),
            output: array(block, "\"output\": ["),
        });
    }
    assert!(!cases.is_empty(), "fixture parsed to no cases");
    cases
}

fn between<'a>(haystack: &'a str, start: &str, end: &str) -> &'a str {
    let rest = &haystack[haystack.find(start).expect("start") + start.len()..];
    &rest[..rest.find(end).expect("end")]
}

fn field<'a>(block: &'a str, key: &str) -> &'a str {
    let rest = &block[block.find(key).expect(key) + key.len()..];
    rest[..rest.find(['\n', ',']).expect("delimiter")]
        .trim()
        .trim_end_matches(',')
}

fn array(block: &str, key: &str) -> Vec<f32> {
    between(block, key, "]")
        .split(',')
        .map(|v| v.trim().parse().expect("float"))
        .collect()
}

#[test]
fn matches_imagej_rank_filters() {
    let path =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../parity/fixtures/RankFilterMinMax.json");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; run ./parity/record.sh", path.display()));

    let cases = parse(&text);
    let mut checked = 0;

    for case in &cases {
        let mut pixels = case.input.clone();
        rank(&mut pixels, case.width, case.radius, case.op);

        assert_eq!(
            pixels,
            case.output,
            "{:?} radius {} on {}x{} diverged from ImageJ",
            case.op,
            case.radius,
            case.width,
            case.input.len() / case.width
        );
        checked += 1;
    }

    assert_eq!(checked, cases.len());
    // The fixture covers 3 image sizes x 6 radii x 2 ops, plus 6 impulses.
    assert!(checked >= 42, "expected at least 42 cases, got {checked}");
}
